const registerNormalizerVersion = `-- name: RegisterNormalizerVersion :one

WITH ins AS (
  INSERT INTO normalizer_versions (name, version, git_sha) VALUES ($1, $2, $3)
  ON CONFLICT DO NOTHING
  RETURNING id
)
SELECT id FROM ins
UNION ALL
SELECT id FROM normalizer_versions WHERE name = $1 AND version = $2 AND git_sha = $3
LIMIT 1
`

type RegisterNormalizerVersionParams struct {
	Name    string
	Version int32
	GitSha  string
}

// Normalizer versions and the canonical writer (J07.3, J07.4); see docs/adr/0016-canonical-writer.md.
// A change never updates a row in place: supersede the old row, insert the new one, then link them
// (superseded_by can only point at a row that exists, and the partial unique index on dedupe_key
// admits one non-superseded row at a time).
func (q *Queries) RegisterNormalizerVersion(ctx context.Context, arg RegisterNormalizerVersionParams) (int32, error) {
	row := q.db.QueryRow(ctx, registerNormalizerVersion, arg.Name, arg.Version, arg.GitSha)
	var id int32
	err := row.Scan(&id)
	return id, err
}

