const upsertDevice = `-- name: UpsertDevice :one
WITH ins AS (
  INSERT INTO devices AS d (id, user_id, provider_id, fingerprint, device_type, manufacturer, model,
                            hardware_version, software_version)
  VALUES ($1, $2, $3, $4, $5, $6,
          $7, $8, $9)
  ON CONFLICT (user_id, provider_id, fingerprint) DO UPDATE SET
    device_type      = COALESCE(EXCLUDED.device_type, d.device_type),
    manufacturer     = COALESCE(EXCLUDED.manufacturer, d.manufacturer),
    model            = COALESCE(EXCLUDED.model, d.model),
    hardware_version = COALESCE(EXCLUDED.hardware_version, d.hardware_version),
    software_version = COALESCE(EXCLUDED.software_version, d.software_version)
  WHERE (d.device_type, d.manufacturer, d.model, d.hardware_version, d.software_version) IS DISTINCT FROM
        (COALESCE(EXCLUDED.device_type, d.device_type), COALESCE(EXCLUDED.manufacturer, d.manufacturer),
         COALESCE(EXCLUDED.model, d.model), COALESCE(EXCLUDED.hardware_version, d.hardware_version),
         COALESCE(EXCLUDED.software_version, d.software_version))
  RETURNING d.id
)
SELECT id FROM ins
UNION ALL
SELECT id FROM devices WHERE user_id = $2 AND provider_id = $3 AND fingerprint = $4
LIMIT 1
`

type UpsertDeviceParams struct {
	ID              uuid.UUID
	UserID          uuid.UUID
	ProviderID      int16
	Fingerprint     string
	DeviceType      *string
	Manufacturer    *string
	Model           *string
	HardwareVersion *string
	SoftwareVersion *string
}

// Descriptive fields only fill in or change; a field the source stops sending keeps its value.
func (q *Queries) UpsertDevice(ctx context.Context, arg UpsertDeviceParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertDevice,
		arg.ID,
		arg.UserID,
		arg.ProviderID,
		arg.Fingerprint,
		arg.DeviceType,
		arg.Manufacturer,
		arg.Model,
		arg.HardwareVersion,
		arg.SoftwareVersion,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const upsertOrigin = `-- name: UpsertOrigin :one
WITH ins AS (
  INSERT INTO data_origins AS o (id, user_id, provider_id, origin_key, name, is_native, relayed_provider_id)
  SELECT $1::uuid, $2::uuid, $3::smallint, $4::text, $5::text, $6::boolean,
         (SELECT k.relayed_provider_id FROM known_relay_origins k
          WHERE k.provider_id = $3::smallint AND $4::text LIKE k.origin_pattern
          ORDER BY k.id LIMIT 1)
  ON CONFLICT (user_id, provider_id, origin_key) DO UPDATE SET name = EXCLUDED.name
  WHERE EXCLUDED.name IS NOT NULL AND o.name IS DISTINCT FROM EXCLUDED.name
  RETURNING o.id, o.relayed_provider_id
)
SELECT id, relayed_provider_id FROM ins
UNION ALL
SELECT id, relayed_provider_id FROM data_origins
WHERE user_id = $2::uuid AND provider_id = $3::smallint AND origin_key = $4::text
LIMIT 1
`

type UpsertOriginParams struct {
	ID         uuid.UUID
	UserID     uuid.UUID
	ProviderID int16
	OriginKey  string
	Name       *string
	IsNative   bool
}

type UpsertOriginRow struct {
	ID                uuid.UUID
	RelayedProviderID *int16
}

// A new origin takes its relay target from known_relay_origins; later edits to the origin win.
func (q *Queries) UpsertOrigin(ctx context.Context, arg UpsertOriginParams) (UpsertOriginRow, error) {
	row := q.db.QueryRow(ctx, upsertOrigin,
		arg.ID,
		arg.UserID,
		arg.ProviderID,
		arg.OriginKey,
		arg.Name,
		arg.IsNative,
	)
	var i UpsertOriginRow
	err := row.Scan(&i.ID, &i.RelayedProviderID)
	return i, err
}
